<?php
require_once 'includes/auth.php'; require_once 'config/db.php'; require_once 'includes/functions.php'; require_permission('purchase_orders.manage');
if ($_SERVER['REQUEST_METHOD']==='POST') { require_post_csrf(); try { $pdo->beginTransaction(); $action=$_POST['action']??''; if($action==='supplier'){ $pdo->prepare('INSERT INTO suppliers(name,contact_name,phone,email) VALUES(?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['contact_name']),trim($_POST['phone']),normalize_email($_POST['email'])]); } elseif($action==='create'){ $supplier=(int)$_POST['supplier_id']; $products=$_POST['qty']??[]; $po='PO-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(2))); $pdo->prepare("INSERT INTO purchase_orders(po_no,supplier_id,created_by,status) VALUES(?,?,?,'draft')")->execute([$po,$supplier,$_SESSION['user_id']]); $id=(int)$pdo->lastInsertId(); $add=$pdo->prepare('INSERT INTO purchase_order_items(purchase_order_id,product_id,qty,unit_cost) SELECT ?,id,?,COALESCE(cost,0) FROM products WHERE id=?'); $total=0; foreach($products as $pid=>$qty) if((int)$qty>0){$add->execute([$id,(int)$qty,(int)$pid]); $cost=$pdo->prepare('SELECT cost FROM products WHERE id=?');$cost->execute([(int)$pid]);$total+=(float)$cost->fetchColumn()*(int)$qty;} $pdo->prepare('UPDATE purchase_orders SET total_amount=? WHERE id=?')->execute([$total,$id]); audit_log('create','purchase_orders',$id,null,['po_no'=>$po],'Low-stock purchase order'); } elseif($action==='receive'){ $id=(int)$_POST['po_id']; $items=$pdo->prepare('SELECT * FROM purchase_order_items WHERE purchase_order_id=?');$items->execute([$id]); foreach($items as $i) updateStock($pdo,$i['product_id'],$i['qty'],$_SESSION['user_id'],'purchase_order','PO #'.$id.' received'); $pdo->prepare("UPDATE purchase_orders SET status='received',received_at=NOW() WHERE id=? AND status IN ('draft','ordered')")->execute([$id]); audit_log('receive','purchase_orders',$id); } $pdo->commit(); $_SESSION['message']='Purchase-order update saved.'; }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Could not save purchase order.';} header('Location: purchase_orders.php');exit; }
$suppliers=$pdo->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();$low=$pdo->query('SELECT * FROM products WHERE stock_qty<=reorder_level ORDER BY stock_qty')->fetchAll();$orders=$pdo->query('SELECT po.*,s.name supplier FROM purchase_orders po LEFT JOIN suppliers s ON s.id=po.supplier_id ORDER BY po.ordered_at DESC LIMIT 30')->fetchAll();$pageTitle='Low stock & purchase orders';include 'includes/header.php'; ?>
<h2>Low-stock alerts & purchase orders</h2><?php foreach(['message'=>'success','error'=>'danger'] as $k=>$t):if(!empty($_SESSION[$k])):?><div class="alert alert-<?= $t ?>"><?=htmlspecialchars($_SESSION[$k]);unset($_SESSION[$k]);?></div><?php endif;endforeach;?><div class="row g-3"><div class="col-lg-8"><form method="post" class="card"><div class="card-header">Create order from low-stock items</div><div class="card-body"><?=csrf_field()?><input type="hidden" name="action" value="create"><select required name="supplier_id" class="form-select mb-3"><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select><table class="table table-sm"><thead><tr><th>Product</th><th>Available</th><th>Reorder level</th><th>Order qty</th></tr></thead><tbody><?php foreach($low as $p):?><tr><td><?=htmlspecialchars($p['name'])?></td><td><?=$p['stock_qty']?></td><td><?=$p['reorder_level']?></td><td><input class="form-control" style="width:90px" name="qty[<?=$p['id']?>]" min="0" type="number" value="<?=max(1,$p['reorder_level']-$p['stock_qty'])?>"></td></tr><?php endforeach;?></tbody></table><button class="btn btn-primary">Create draft PO</button></div></form></div><div class="col-lg-4"><form method="post" class="card"><div class="card-header">Add supplier</div><div class="card-body"><?=csrf_field()?><input type="hidden" name="action" value="supplier"><input required class="form-control mb-2" name="name" placeholder="Supplier name"><input class="form-control mb-2" name="contact_name" placeholder="Contact"><input class="form-control mb-2" name="phone" placeholder="Phone"><input class="form-control mb-2" name="email" placeholder="Email"><button class="btn btn-outline-primary">Save supplier</button></div></form></div></div><h4 class="mt-4">Purchase-order history</h4><table class="table table-sm"><thead><tr><th>PO</th><th>Supplier</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=htmlspecialchars($o['po_no'])?></td><td><?=htmlspecialchars($o['supplier']??'-')?></td><td><?=$o['status']?></td><td>KSh <?=number_format($o['total_amount'],2)?></td><td><?php if($o['status']!=='received'&&$o['status']!=='cancelled'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="receive"><input type="hidden" name="po_id" value="<?=$o['id']?>"><button class="btn btn-sm btn-success">Receive stock</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php include 'includes/footer.php'; ?>
